    for (let i = 0; i < frame.length; i += 2) {
        let byte = parseInt(frame.substring(i, i + 2), 16);
        array.push(byte);
    }

    if(array[0] == 252 && array[1] == 251){


   //const array = bytes.slice(0,temp.length);

   console.log("array=", array);

